R.append((7359452,
("Guiso de pollo", "Agregar legumbres a un guiso aporta proteína y fibra adicionales.", "4", "346 g",
 ["4 pechugas de pollo pequeñas sin piel (500 g)", "1 cebolla grande, picada", "2 dientes de ajo, machacados", "2 pimientos verdes, sin semillas y picados", "2 cucharadas de mejorana fresca o media cucharada de mejorana seca", "1 lata de 400 g de tomates picados", "150 ml de caldo de pollo bajo en sal", "1 lata de 420 g de frijoles borlotti, escurridos y enjuagados", "2 cucharadas de pasta de tomate", "pimienta negra recién molida"],
 ["Caliente una olla grande antiadherente y fría las pechugas de pollo hasta que se doren por ambos lados. Puede agregar un poco de agua a la olla si el pollo se pega.", "Agregue la cebolla, el ajo y los pimientos y siga friendo de 2 a 3 minutos.", "Añada los tomates picados, el caldo de pollo, los frijoles, la pasta de tomate, la pimienta recién molida y las hierbas.", "Mezcle bien, deje que hierva, tape y cocine a fuego lento de 40 a 45 minutos."],
 ["Este platillo también queda bien con pavo.", "Si lo prefiere, puede usar frijoles mixtos o garbanzos en lugar de frijoles borlotti.", "Instrucciones para congelar: Se puede congelar una vez cocido. Descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 3"], []),
("يخنة الدجاج", "تضيف البقوليات إلى اليخنة مزيدًا من البروتين والألياف.", "4", "346 غ",
 ["4 صدور دجاج صغيرة بلا جلد (500 غ)", "1 بصلة كبيرة، مفرومة", "2 فص ثوم، مهروس", "2 فلفل رومي أخضر، منزوع البذور ومفروم", "2 ملعقة كبيرة مردقوش طازج أو نصف ملعقة كبيرة مردقوش مجفف", "1 علبة 400 غ طماطم مفرومة", "150 مل مرق دجاج قليل الملح", "1 علبة 420 غ فاصولياء بورلوتي، مصفّاة ومشطوفة", "2 ملعقة كبيرة معجون طماطم", "فلفل أسود مطحون طازجًا"],
 ["سخّن قدرًا كبيرًا غير لاصق وقلِّ صدور الدجاج حتى تحمرّ من كل جانب. يمكنك إضافة كمية قليلة من الماء إلى القدر إذا التصق الدجاج به.", "أضف البصل والثوم والفلفل الرومي واستمر في التقليب لمدة 2–3 دقائق.", "أضف الطماطم المفرومة ومرق الدجاج والفاصولياء ومعجون الطماطم والفلفل المطحون طازجًا والأعشاب.", "قلّب جيدًا واتركه يغلي، ثم غطِّه واتركه على نار هادئة لمدة 40–45 دقيقة."],
 ["يناسب هذا الطبق لحم الديك الرومي أيضًا.", "يمكنك استخدام فاصولياء مشكّلة أو حمّص بدلًا من فاصولياء بورلوتي إذا فضّلت.", "تعليمات التجميد: يصلح للتجميد بعد الطهي. أذبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا تمامًا في كل أجزائه.", "حصص الفاكهة/الخضار لكل حصة: 3"], [])))
R.append((7359781,
("Sopa cremosa de maíz con crutones de camote", "Una sopa cremosa de maíz y verduras cubierta con pequeños cubos de camote asado con un toque ahumado.", "2", "510 g",
 ["1 camote (150 g), cortado en cubos de 1 cm", "1 cucharadita de aceite", "1 cucharadita colmada de pimentón ahumado", "1 cucharadita de aceite", "1 cebolla grande, picada finamente", "1 zanahoria, en cubos", "1 tallo de apio, en rebanadas finas", "180 g de maíz dulce congelado", "una buena pizca de pimienta blanca", "1 cucharada de harina de trigo", "1 cubo de caldo de verduras reducido en sal, disuelto en 250 ml de agua", "300 ml de leche descremada", "1 cucharada de cebollín fresco, picado", "un buen molido de pimienta negra"],
 ["Precaliente el horno a 180 °C (gas 4). Primero, prepare los crutones de camote. En un tazón grande, rocíe los cubos de camote con 1 cucharadita de aceite y revuélvalos para cubrirlos de manera uniforme. Espolvoree con el pimentón ahumado, revuelva de nuevo y extiéndalos en una charola para hornear. Hornee de 25 a 35 minutos, volteándolos con frecuencia.", "Mientras tanto, prepare la sopa. Caliente el aceite de oliva en una olla grande y fría la cebolla de 3 a 4 minutos. Agregue la zanahoria, el apio, el maíz dulce y la pimienta blanca. Revuelva durante 3 minutos y espolvoree con la harina.", "Incorpore poco a poco el caldo de verduras hasta que espese. Tape, baje el fuego y cocine a fuego lento durante 5 minutos.", "Incorpore lentamente la leche, revolviendo un par de minutos, y vuelva a llevar a fuego lento.", "Sirva la sopa en tazones y espolvoree con un poco de cebollín picado y pimienta negra recién molida. Cubra con los crutones de camote, más cebollín fresco y pimienta negra."],
 ["Si la sopa queda demasiado espesa, incorpore lentamente un poco más de leche.", "Puede agregar cubos de salmón fresco o unos camarones grandes para preparar una sopa cremosa de maíz y mariscos.", "Instrucciones para congelar: Congele los crutones por separado. Descongele la sopa en el microondas o a fuego muy bajo hasta que esté muy caliente.", "Porciones de fruta/verdura por porción: 3"], []),
("شوربة الذرة الكريمية مع مكعبات البطاطا الحلوة المحمّصة", "شوربة كريمية بالذرة والخضار تُزيَّن بمكعبات صغيرة من البطاطا الحلوة المشوية بنكهة مدخنة.", "2", "510 غ",
 ["1 حبة بطاطا حلوة (150 غ)، مقطّعة مكعبات 1 سم", "1 ملعقة صغيرة زيت", "1 ملعقة صغيرة مكوّمة بابريكا مدخنة", "1 ملعقة صغيرة زيت", "1 بصلة كبيرة، مفرومة ناعمًا", "1 جزرة، مقطّعة مكعبات", "1 عود كرفس، مقطّع شرائح رفيعة", "180 غ ذرة حلوة مجمّدة", "رشة كبيرة من الفلفل الأبيض", "1 ملعقة كبيرة دقيق عادي", "1 مكعب مرق خضار قليل الملح، مذاب في 250 مل ماء", "300 مل حليب خالٍ من الدسم", "1 ملعقة كبيرة ثوم معمر (شيف) طازج مفروم", "رشة كبيرة من الفلفل الأسود المطحون"],
 ["سخّن الفرن مسبقًا على 180° مئوية (علامة الغاز 4). ابدأ بتحضير مكعبات البطاطا الحلوة. في وعاء كبير، رشّ مكعبات البطاطا الحلوة بملعقة صغيرة من الزيت وحرّكها لتتغلف بالتساوي. رشّها بالبابريكا المدخنة وحرّكها مرة أخرى وانشرها على صينية خبز. اخبزها لمدة 25–35 دقيقة مع تقليبها بانتظام.", "في الأثناء، حضّر الشوربة. سخّن زيت الزيتون في قدر كبير وقلِّ البصل لمدة 3–4 دقائق. أضف الجزر والكرفس والذرة الحلوة والفلفل الأبيض. قلّب لمدة 3 دقائق ثم رشّ الدقيق.", "أضف مرق الخضار تدريجيًا مع التحريك حتى يثخن. غطِّ ثم اخفض الحرارة واتركه على نار هادئة لمدة 5 دقائق.", "أضف الحليب ببطء مع التحريك لدقيقتين وأعدها إلى الغليان الهادئ.", "اسكب الشوربة في أوعية ورشّ عليها قليلًا من الثوم المعمر المفروم وبعض الفلفل الأسود المطحون طازجًا. زيّنها بمكعبات البطاطا الحلوة المحمّصة والثوم المعمر الطازج والفلفل الأسود."],
 ["إذا أصبحت الشوربة ثخينة جدًا، فأضف ببطء قليلًا من الحليب مع التحريك.", "يمكنك إضافة مكعبات من السلمون الطازج أو بعض الروبيان الكبير لتحضير شوربة ذرة بالمأكولات البحرية.", "تعليمات التجميد: جمّد المكعبات المحمّصة على حدة. أذب الشوربة في الميكروويف أو على نار هادئة جدًا حتى تصبح ساخنة تمامًا.", "حصص الفاكهة/الخضار لكل حصة: 3"], [])))
R.append((7363285,
("Fufu con sopa picante de pollo", "Una sopa tradicional de África Occidental, picante y reconfortante. Se sirve con fufu de plátano macho.", "4", "435 g",
 ["2 cucharaditas de aceite de canola", "1 cebolla grande, picada", "2 pechugas de pollo deshuesadas y sin piel (aprox. 300 g), cortadas en trozos pequeños", "2 zanahorias medianas, cortadas en trozos pequeños", "1 calabacita, cortada en trozos", "2 cucharaditas de curry en polvo", "una buena pizca de nuez moscada", "1 cucharadita rasa de pimentón", "1 cucharada de pasta de tomate", "2 chiles rojos, cortados en rodajas", "1 lata de 400 g de tomates picados", "1 cubo de caldo de pollo reducido en sal, disuelto en 500 ml de agua", "400 ml de agua", "200 g de harina de plátano macho para fufu"],
 ["Caliente el aceite en una olla y agregue la cebolla. Cocine durante 4 minutos, revolviendo con frecuencia. Agregue el pollo y la zanahoria y cocine otros 4 minutos, revolviendo también con frecuencia.", "Añada la calabacita, el curry en polvo, la nuez moscada, el pimentón y la pasta de tomate, y mezcle bien.", "Agregue los chiles, los tomates y el caldo, deje que hierva, baje el fuego, tape y cocine a fuego lento durante 12 minutos.", "Mientras tanto, ponga 400 ml de agua en una olla y llévela al punto de ebullición; baje el fuego e incorpore la harina para fufu. Siga revolviendo de 3 a 4 minutos, hasta que se absorba toda la harina y no queden grumos. Retire del fuego, bata enérgicamente con una cuchara de madera y siga mezclando durante 2 minutos hasta obtener una masa suave.", "Humedezca sus manos y divida el fufu en cuatro bolas. Reparta la sopa en cuatro tazones y coloque con cuidado una porción de fufu sobre cada sopa picante para servir."],
 ["Puede preparar la sopa picante con cordero o res en lugar de pollo.", "Para una versión vegana o vegetariana, sustituya el pollo por una berenjena mediana picada y 200 g de champiñones.", "Porciones de fruta/verdura por porción: 2"], []),
("فوفو مع شوربة الدجاج الحارة", "شوربة تقليدية من غرب أفريقيا، حارة ومشبعة. تُقدَّم مع فوفو الموز الأخضر (البلانتين).", "4", "435 غ",
 ["2 ملعقة صغيرة زيت اللفت", "1 بصلة كبيرة، مفرومة", "2 صدر دجاج منزوع العظم والجلد (حوالي 300 غ)، مقطّع قطعًا صغيرة", "2 جزرة متوسطة، مقطّعة قطعًا صغيرة", "1 كوسا، مقطّعة قطعًا", "2 ملعقة صغيرة مسحوق كاري", "رشة كبيرة من جوزة الطيب", "1 ملعقة صغيرة مستوية بابريكا", "1 ملعقة كبيرة معجون طماطم", "2 فلفل أحمر حار، مقطّع حلقات", "1 علبة 400 غ طماطم مفرومة", "1 مكعب مرق دجاج قليل الملح، مذاب في 500 مل ماء", "400 مل ماء", "200 غ دقيق فوفو من الموز الأخضر (البلانتين)"],
 ["سخّن الزيت في قدر وأضف البصل. اطبخه لمدة 4 دقائق مع التحريك باستمرار. أضف الدجاج والجزر واطبخ لمدة 4 دقائق أخرى مع التحريك باستمرار أيضًا.", "أضف الكوسا ومسحوق الكاري وجوزة الطيب والبابريكا ومعجون الطماطم واخلط جيدًا.", "أضف الفلفل الحار والطماطم والمرق، واتركه يغلي، ثم اخفض الحرارة وغطِّه واتركه على نار هادئة لمدة 12 دقيقة.", "في الأثناء، ضع 400 مل ماء في قدر وأوصله إلى درجة الغليان، ثم اخفض الحرارة وأضف دقيق الفوفو مع التحريك. استمر في التحريك لمدة 3–4 دقائق حتى يُمتصّ كل الدقيق ولا تبقى كتل. ارفعه عن النار واخفقه بقوة بملعقة خشبية وواصل الخلط لمدة دقيقتين حتى تحصل على عجينة ناعمة.", "بلّل يديك وقسّم الفوفو إلى أربع كرات. وزّع الشوربة على أربعة أوعية وضع بحذر حصة من الفوفو فوق كل شوربة حارة للتقديم."],
 ["يمكنك تحضير الشوربة الحارة بلحم الضأن أو البقر بدلًا من الدجاج.", "للحصول على نسخة نباتية، استبدل الدجاج بحبة باذنجان متوسطة مفرومة و200 غ فطر.", "حصص الفاكهة/الخضار لكل حصة: 2"], [])))
